	{ ipa: "kà", paiboon: "gà", label: "short vowel a" },
	{ ipa: "kàː", paiboon: "gàa", label: "long vowel a" },
	{ ipa: "tì", paiboon: "dtì", label: "short vowel i" },
	{ ipa: "tìː", paiboon: "dtìi", label: "long vowel i" },
