	{ ipa: "tam", paiboon: "dtam", label: "unaspirated t" },
	{ ipa: "tʰam", paiboon: "tham", label: "aspirated t" },
	{ ipa: "kai", paiboon: "gai", label: "unaspirated k" },
	{ ipa: "kʰai", paiboon: "khai", label: "aspirated k" },
	{ ipa: "tɕai", paiboon: "jai", label: "unaspirated affricate" },
